  , CASE WHEN `cuiPeakMaxC` IS NOT NULL AND trim(cast(`cuiPeakMaxC` AS STRING)) != '' THEN cast(`cuiPeakMaxC` AS DOUBLE) ELSE NULL END AS `cuiPeakMaxC`
  , CASE WHEN `cuiPeakMinC` IS NOT NULL AND trim(cast(`cuiPeakMinC` AS STRING)) != '' THEN cast(`cuiPeakMinC` AS DOUBLE) ELSE NULL END AS `cuiPeakMinC`
  , CASE WHEN `cuiSusceptibilityMaxC` IS NOT NULL AND trim(cast(`cuiSusceptibilityMaxC` AS STRING)) != '' THEN cast(`cuiSusceptibilityMaxC` AS DOUBLE) ELSE NULL END AS `cuiSusceptibilityMaxC`
  , CASE WHEN `cuiSusceptibilityMinC` IS NOT NULL AND trim(cast(`cuiSusceptibilityMinC` AS STRING)) != '' THEN cast(`cuiSusceptibilityMinC` AS DOUBLE) ELSE NULL END AS `cuiSusceptibilityMinC`
  , cast(`description` AS STRING) AS `description`
  , cast(`name` AS STRING) AS `name`
FROM `{{energyBaseRawDb}}`.`Material`
